sealed class AppException(message: String): kotlin.Exception(message) {
        
        class ApiException(message: String) : AppException(message)
        
        class NetworkException(message: String) : AppException(message)
        
        class AuthException(message: String) : AppException(message)
        
        class NotFoundException(message: String) : AppException(message)
        
        class PaymentRequired(message: String) : AppException(message)
        
        class ServerException(message: String) : AppException(message)
        
        class ParseException(message: String) : AppException(message)
        
        class EmptyField(message: String) : AppException(message)
        
        class Unauthorized(message: String) : AppException(message)
        
        class BadRequest(message: String) : AppException(message)
        
        class EmailInvalid(message: String) : AppException(message)
        
        class Conflict(message: String) : AppException(message)
        
        class Unknown(message: String) : AppException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeAppError : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        
            return when(buf.getInt()) {
            1 -> AppException.ApiException(FfiConverterString.read(buf))
            2 -> AppException.NetworkException(FfiConverterString.read(buf))
            3 -> AppException.AuthException(FfiConverterString.read(buf))
            4 -> AppException.NotFoundException(FfiConverterString.read(buf))
            5 -> AppException.PaymentRequired(FfiConverterString.read(buf))
            6 -> AppException.ServerException(FfiConverterString.read(buf))
            7 -> AppException.ParseException(FfiConverterString.read(buf))
            8 -> AppException.EmptyField(FfiConverterString.read(buf))
            9 -> AppException.Unauthorized(FfiConverterString.read(buf))
            10 -> AppException.BadRequest(FfiConverterString.read(buf))
            11 -> AppException.EmailInvalid(FfiConverterString.read(buf))
            12 -> AppException.Conflict(FfiConverterString.read(buf))
            13 -> AppException.Unknown(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: AppException): ULong {
        return 4UL
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
            is AppException.ApiException -> {
                buf.putInt(1)
                Unit
            }
            is AppException.NetworkException -> {
                buf.putInt(2)
                Unit
            }
            is AppException.AuthException -> {
                buf.putInt(3)
                Unit
            }
            is AppException.NotFoundException -> {
                buf.putInt(4)
                Unit
            }
            is AppException.PaymentRequired -> {
                buf.putInt(5)
                Unit
            }
            is AppException.ServerException -> {
                buf.putInt(6)
                Unit
            }
            is AppException.ParseException -> {
                buf.putInt(7)
                Unit
            }
            is AppException.EmptyField -> {
                buf.putInt(8)
                Unit
            }
            is AppException.Unauthorized -> {
                buf.putInt(9)
                Unit
            }
            is AppException.BadRequest -> {
                buf.putInt(10)
                Unit
            }
            is AppException.EmailInvalid -> {
                buf.putInt(11)
                Unit
            }
            is AppException.Conflict -> {
                buf.putInt(12)
                Unit
            }
            is AppException.Unknown -> {
                buf.putInt(13)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




